#include "bench/drivers/drivers.hh"
#include "base/runtime/memory.hh"

#define POSTGRES_SCHEMA "CREATE TABLE items ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, a BIGINT, b TEXT COLLATE \"C\", c DOUBLE PRECISION, d BIGINT ); CREATE TABLE orders ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, item BIGINT, qty BIGINT, note TEXT COLLATE \"C\" ); CREATE TABLE log ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, v TEXT COLLATE \"C\" )"
#define POSTGRES_START "SET client_min_messages = warning; DROP SCHEMA IF EXISTS strata_bench CASCADE; CREATE SCHEMA strata_bench; SET search_path TO strata_bench"
#define POSTGRES_END "DROP SCHEMA IF EXISTS strata_bench CASCADE"

namespace bench {

	static bool binary_type ( uint32_t type ) {

		return type == WIRE_INT8 || type == WIRE_INT4 || type == WIRE_INT2 || type == WIRE_FLOAT8 || type == WIRE_FLOAT4 || type == WIRE_BOOL || type == WIRE_OID;

	}

	static void translate ( const char* sql, base::text& out ) {

		uint32_t next = 1;
		bool quoted = false;
		const char* at = sql;

		while ( *at ) {

			char item = *at++;

			if ( item == '\'' )
				quoted = !quoted;

			if ( item != '?' || quoted ) {

				out.add ( item );

				continue;

			}

			out.add ( '$' );

			if ( *at < '0' || *at > '9' ) {

				out.number ( next++ );

				continue;

			}

			while ( *at >= '0' && *at <= '9' )
				out.add ( *at++ );

		}

	}

	static bool postgres_open ( void* state, const char* path ) {

		postgres_side& side = *static_cast < postgres_side* > ( state );

		( void ) path;

		return wire_open ( side.link, side.settings ) && wire_simple ( side.link, POSTGRES_START );

	}

	static void postgres_close ( void* state ) {

		postgres_side& side = *static_cast < postgres_side* > ( state );

		if ( side.link.socket && !side.link.broken )
			wire_simple ( side.link, POSTGRES_END );

		wire_close ( side.link );

	}

	static bool postgres_exec ( void* state, const char* sql ) {

		return wire_simple ( static_cast < postgres_side* > ( state )->link, sql );

	}

	static bool read_description ( wire_link& link, wire_statement& item ) {

		bool fine = true;
		wire_message message;

		for ( ;; ) {

			if ( !wire_next ( link, message ) )
				return false;

			if ( message.type == 't' ) {

				uint32_t count = message.size >= 2 ? wire_read16 ( message.body ) : 0;

				if ( count > WIRE_PARAMETERS || message.size < 2 + count * 4 ) {

					wire_fail ( link, "the statement has more parameters than the Postgres driver keeps" );
					fine = false;

					continue;

				}

				item.parameter_count = count;

				for ( uint32_t i = 0; i < count; i++ )
					item.parameter_types [ i ] = wire_read32 ( message.body + 2 + i * 4 );

			} else if ( message.type == 'T' ) {

				uint32_t count = message.size >= 2 ? wire_read16 ( message.body ) : 0;
				uint32_t at = 2;

				if ( count > WIRE_COLUMNS ) {

					wire_fail ( link, "the statement has more columns than the Postgres driver keeps" );
					fine = false;

					continue;

				}

				for ( uint32_t i = 0; i < count; i++ ) {

					while ( at < message.size && message.body [ at ] )
						at++;

					at++;

					if ( at + 18 > message.size ) {

						wire_fail ( link, "Postgres described the columns in a malformed message" );
						fine = false;

						break;

					}

					item.column_types [ i ] = wire_read32 ( message.body + at + 6 );
					item.column_formats [ i ] = binary_type ( item.column_types [ i ] ) ? 1 : 0;
					at += 18;

				}

				item.column_count = count;

			} else if ( message.type == 'E' ) {

				wire_note_error ( link, message );
				fine = false;

			} else if ( message.type == 'Z' ) {

				link.status = message.size ? message.body [ 0 ] : 'I';

				return fine;

			}

		}

	}

	static void* postgres_prepare ( void* state, const char* sql ) {

		postgres_side& side = *static_cast < postgres_side* > ( state );
		wire_statement* item = base::make < wire_statement > ( 1 );

		if ( !item ) {

			wire_fail ( side.link, "out of memory for a Postgres statement" );

			return nullptr;

		}

		base::text name;
		base::text query;

		name.add ( "strata_" ).number ( ++side.statements );
		base::copy_text ( item->name, sizeof ( item->name ), name.value ( ) );
		translate ( sql, query );

		wire_begin ( side.link, 'P' );
		wire_string ( side.link, item->name );
		wire_string ( side.link, query.value ( ) );
		wire_int16 ( side.link, 0 );
		wire_end ( side.link );
		wire_begin ( side.link, 'D' );
		wire_bytes ( side.link, "S", 1 );
		wire_string ( side.link, item->name );
		wire_end ( side.link );
		wire_begin ( side.link, 'S' );
		wire_end ( side.link );

		if ( !wire_flush ( side.link ) || !read_description ( side.link, *item ) ) {

			base::release ( item );

			return nullptr;

		}

		return item;

	}

	static void put_number ( wire_link& link, uint32_t type, int64_t whole, double real, bool is_real ) {

		if ( type == WIRE_INT8 ) {

			uint64_t bits = static_cast < uint64_t > ( is_real ? static_cast < int64_t > ( real ) : whole );

			wire_int32 ( link, 8 );
			wire_int32 ( link, static_cast < int32_t > ( bits >> 32 ) );
			wire_int32 ( link, static_cast < int32_t > ( bits ) );

		} else if ( type == WIRE_INT4 || type == WIRE_OID ) {

			wire_int32 ( link, 4 );
			wire_int32 ( link, static_cast < int32_t > ( is_real ? static_cast < int64_t > ( real ) : whole ) );

		} else if ( type == WIRE_INT2 ) {

			wire_int32 ( link, 2 );
			wire_int16 ( link, static_cast < int32_t > ( is_real ? static_cast < int64_t > ( real ) : whole ) );

		} else if ( type == WIRE_BOOL ) {

			uint8_t value = ( is_real ? real != 0 : whole != 0 ) ? 1 : 0;

			wire_int32 ( link, 1 );
			wire_bytes ( link, &value, 1 );

		} else if ( type == WIRE_FLOAT8 ) {

			double value = is_real ? real : static_cast < double > ( whole );
			uint64_t bits = 0;

			base::copy ( &bits, &value, 8 );
			wire_int32 ( link, 8 );
			wire_int32 ( link, static_cast < int32_t > ( bits >> 32 ) );
			wire_int32 ( link, static_cast < int32_t > ( bits ) );

		} else if ( type == WIRE_FLOAT4 ) {

			float value = static_cast < float > ( is_real ? real : static_cast < double > ( whole ) );
			uint32_t bits = 0;

			base::copy ( &bits, &value, 4 );
			wire_int32 ( link, 4 );
			wire_int32 ( link, static_cast < int32_t > ( bits ) );

		} else {

			base::text written;

			if ( is_real )
				written.real ( real );
			else
				written.signed_number ( whole );

			wire_int32 ( link, static_cast < int32_t > ( written.size ) );
			wire_bytes ( link, written.data, written.size );

		}

	}

	static bool read_decimal ( const uint8_t* at, uint32_t size, double& out ) {

		double value = 0;
		double scale = 1;
		bool negative = false;
		bool fraction = false;
		uint32_t i = 0;

		if ( i < size && ( at [ i ] == '-' || at [ i ] == '+' ) )
			negative = at [ i++ ] == '-';

		if ( i == size )
			return false;

		for ( ; i < size; i++ ) {

			if ( at [ i ] == '.' && !fraction ) {

				fraction = true;

				continue;

			}

			if ( at [ i ] < '0' || at [ i ] > '9' )
				return false;

			value = value * 10 + ( at [ i ] - '0' );

			if ( fraction )
				scale *= 10;

		}

		out = negative ? -value / scale : value / scale;

		return true;

	}

	static uint64_t column_hash ( uint32_t type, int16_t format, const uint8_t* at, uint32_t size ) {

		if ( format == 1 ) {

			if ( type == WIRE_INT8 && size == 8 )
				return number_hash ( static_cast < double > ( static_cast < int64_t > ( wire_read64 ( at ) ) ) );

			if ( ( type == WIRE_INT4 || type == WIRE_OID ) && size == 4 )
				return number_hash ( static_cast < double > ( static_cast < int32_t > ( wire_read32 ( at ) ) ) );

			if ( type == WIRE_INT2 && size == 2 )
				return number_hash ( static_cast < double > ( static_cast < int16_t > ( wire_read16 ( at ) ) ) );

			if ( type == WIRE_BOOL && size == 1 )
				return number_hash ( at [ 0 ] ? 1.0 : 0.0 );

			if ( type == WIRE_FLOAT8 && size == 8 ) {

				uint64_t bits = wire_read64 ( at );
				double value = 0;

				base::copy ( &value, &bits, 8 );

				return number_hash ( value );

			}

			if ( type == WIRE_FLOAT4 && size == 4 ) {

				uint32_t bits = wire_read32 ( at );
				float value = 0;

				base::copy ( &value, &bits, 4 );

				return number_hash ( value );

			}

		}

		double number = 0;

		if ( type == WIRE_NUMERIC && read_decimal ( at, size, number ) )
			return number_hash ( number );

		return text_hash ( at, size );

	}

	static void tally_row ( const wire_statement& item, const wire_message& message, bench_tally& tally ) {

		uint32_t count = message.size >= 2 ? wire_read16 ( message.body ) : 0;
		uint32_t at = 2;
		uint64_t row = 0;

		for ( uint32_t c = 0; c < count && at + 4 <= message.size; c++ ) {

			int32_t size = static_cast < int32_t > ( wire_read32 ( message.body + at ) );
			uint64_t hash = 0x5555;

			at += 4;

			if ( size >= 0 && at + static_cast < uint32_t > ( size ) <= message.size ) {

				uint32_t type = c < item.column_count ? item.column_types [ c ] : WIRE_TEXT;
				int16_t format = c < item.column_count ? item.column_formats [ c ] : 0;

				hash = column_hash ( type, format, message.body + at, static_cast < uint32_t > ( size ) );
				at += static_cast < uint32_t > ( size );

			}

			row = row * 0x100000001B3ull ^ hash;

		}

		count_row ( tally, row );

	}

	static bool postgres_run ( void* state, void* statement, const bench_value* values, uint32_t count, bench_tally& tally ) {

		postgres_side& side = *static_cast < postgres_side* > ( state );
		wire_statement& item = *static_cast < wire_statement* > ( statement );
		wire_link& link = side.link;

		wire_begin ( link, 'B' );
		wire_bytes ( link, "", 1 );
		wire_string ( link, item.name );
		wire_int16 ( link, static_cast < int32_t > ( count ) );

		for ( uint32_t i = 0; i < count; i++ ) {

			uint32_t type = i < item.parameter_count ? item.parameter_types [ i ] : 0;

			wire_int16 ( link, binary_type ( type ) && values [ i ].kind != BENCH_TEXT ? 1 : 0 );

		}

		wire_int16 ( link, static_cast < int32_t > ( count ) );

		for ( uint32_t i = 0; i < count; i++ ) {

			const bench_value& value = values [ i ];
			uint32_t type = i < item.parameter_count ? item.parameter_types [ i ] : 0;

			if ( value.kind == BENCH_NULL )
				wire_int32 ( link, -1 );
			else if ( value.kind == BENCH_TEXT ) {

				wire_int32 ( link, static_cast < int32_t > ( value.size ) );
				wire_bytes ( link, value.text, value.size );

			} else
				put_number ( link, binary_type ( type ) ? type : 0, value.integer, value.real, value.kind == BENCH_REAL );

		}

		wire_int16 ( link, static_cast < int32_t > ( item.column_count ) );

		for ( uint32_t c = 0; c < item.column_count; c++ )
			wire_int16 ( link, item.column_formats [ c ] );

		wire_end ( link );
		wire_begin ( link, 'E' );
		wire_bytes ( link, "", 1 );
		wire_int32 ( link, 0 );
		wire_end ( link );
		wire_begin ( link, 'S' );
		wire_end ( link );

		if ( !wire_flush ( link ) )
			return false;

		bool fine = true;
		wire_message message;

		for ( ;; ) {

			if ( !wire_next ( link, message ) )
				return false;

			if ( message.type == 'D' )
				tally_row ( item, message, tally );
			else if ( message.type == 'E' ) {

				wire_note_error ( link, message );
				fine = false;

			} else if ( message.type == 'Z' ) {

				link.status = message.size ? message.body [ 0 ] : 'I';

				return fine;

			}

		}

	}

	static void postgres_finish ( void* state, void* statement ) {

		postgres_side& side = *static_cast < postgres_side* > ( state );
		wire_statement* item = static_cast < wire_statement* > ( statement );

		if ( !side.link.broken ) {

			wire_begin ( side.link, 'C' );
			wire_bytes ( side.link, "S", 1 );
			wire_string ( side.link, item->name );
			wire_end ( side.link );
			wire_begin ( side.link, 'S' );
			wire_end ( side.link );

			if ( wire_flush ( side.link ) )
				wire_settle ( side.link );

		}

		base::release ( item );

	}

	static const char* postgres_problem ( void* state ) {

		return static_cast < postgres_side* > ( state )->link.problem.value ( );

	}

	static void postgres_release ( void* state ) {

		static_cast < postgres_side* > ( state )->~postgres_side ( );

	}

	bool make_postgres_driver ( bench_driver& out, const char* connection ) {

		postgres_side* side = base::make < postgres_side > ( 1 );

		out = { };

		if ( !side )
			return false;

		if ( !read_settings ( connection, side->settings ) ) {

			side->~postgres_side ( );
			base::release ( side );

			return false;

		}

		base::text where;

		where.add ( side->settings.host ).add ( ':' ).number ( side->settings.port ).add ( '/' ).add ( side->settings.database ).add ( ", schema strata_bench" );
		base::copy_text ( side->where, sizeof ( side->where ), where.value ( ) );
		base::copy_text ( side->link.server_version, sizeof ( side->link.server_version ), "?" );

		out.name = "Postgres";
		out.version = side->link.server_version;
		out.detail = side->where;
		out.note = "Strata runs inside the benchmark process; Postgres answers over TCP the way it would for an app server, so each statement pays one round trip";
		out.schema = POSTGRES_SCHEMA;
		out.state = side;
		out.open = postgres_open;
		out.close = postgres_close;
		out.exec = postgres_exec;
		out.prepare = postgres_prepare;
		out.run = postgres_run;
		out.finish = postgres_finish;
		out.problem = postgres_problem;
		out.release = postgres_release;

		return true;

	}

}
